import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"服务与积分","description":"","frontmatter":{},"headers":[],"relativePath":"zh/online/credits.md","filePath":"zh/online/credits.md","lastUpdated":1792570296000}'),l={name:"zh/online/credits.md"};function n(i,e,s,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="服务与积分" tabindex="-1">服务与积分 <a class="header-anchor" href="#服务与积分" aria-label="Permalink to &quot;服务与积分&quot;">​</a></h1><p>PaperSeek 服务是在线版的默认模式：模型由 PaperSeek 提供，任务消耗每日积分，不使用你自己的服务商账户。</p><h2 id="使用-paperseek-服务" tabindex="-1">使用 PaperSeek 服务 <a class="header-anchor" href="#使用-paperseek-服务" aria-label="Permalink to &quot;使用 PaperSeek 服务&quot;">​</a></h2><ol><li>登录。默认即为 PaperSeek 服务。</li><li>填写研究问题，选择数据源和检索预算。</li><li>开始检索。表单会显示本次任务消耗的积分和今日剩余积分。</li></ol><p>检索和综述都使用 <strong>Default</strong>，即 PaperSeek 选定的内置模型。初排序在 <strong>设置 › 模型服务</strong> 中配置。可用数据源以应用中显示的为准。</p><h2 id="积分" tabindex="-1">积分 <a class="header-anchor" href="#积分" aria-label="Permalink to &quot;积分&quot;">​</a></h2><p>公测期间，每个账户每天获得 <strong>20 免费积分</strong>。只有 PaperSeek 服务消耗积分：</p><table tabindex="0"><thead><tr><th>任务</th><th>积分</th></tr></thead><tbody><tr><td>文献检索</td><td>1</td></tr><tr><td>文献计量</td><td>1</td></tr><tr><td>文献综述</td><td>一整篇 5</td></tr></tbody></table><p>积分在提交任务时扣除。一篇综述只扣一次，由它的第一个写作任务扣除；同一篇综述之后重新生成大纲、写作正文、重写章节都不再扣。挑选文献时的<strong>按主题自动挑选</strong>免费，也不计入写作次数。任务失败或被取消会退回积分；带警告完成的任务不退回。</p><p>剩余积分显示在侧栏和 <strong>设置 › 用户</strong> 中，并注明每日恢复时间。</p><h2 id="申请更多积分" tabindex="-1">申请更多积分 <a class="header-anchor" href="#申请更多积分" aria-label="Permalink to &quot;申请更多积分&quot;">​</a></h2><p>公测期间如需更大用量，请发邮件至 <a href="mailto:support@paperseek.app" target="_blank" rel="noreferrer">support@paperseek.app</a>，正文写明账户 ID（在 <strong>设置 › 用户</strong> 中复制）、所在单位和你使用 PaperSeek 的方式。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="./byok">自带密钥</a> — 运行任务不消耗积分。</li><li><a href="./account">账户与登录</a> — 积分显示和账户设置。</li></ul>',14)])])}const k=a(l,[["render",n]]);export{_ as __pageData,k as default};
